; Workboy (U) (Unreleased) - sound driver (Source engine, version 1) and data
; Generated by tools/gen_src.py. Assembles byte-identical with RGBDS 1.0.0.

INCLUDE "hardware.inc"
DEF SRC_VER EQU 1
INCLUDE "source_sound.inc"

DEF wSndV1State            EQU $C3B2	; voice 1 (ch1): 0 = sounding, $FF = idle
DEF wSndV1EnvPtr           EQU $C3B3
DEF wSndV1EnvDelta         EQU $C3B5
DEF wSndV1EnvCount         EQU $C3B6
DEF wSndV1EnvRate          EQU $C3B7
DEF wSndV1EnvTimer         EQU $C3B8
DEF wSndV1FreqLo           EQU $C3B9
DEF wSndV1FreqHi           EQU $C3BA
DEF wSndV1Dur              EQU $C3BB
DEF wSndV2State            EQU $C3BC	; voice 2 (ch2)
DEF wSndV2EnvPtr           EQU $C3BD
DEF wSndV2EnvDelta         EQU $C3BF
DEF wSndV2EnvCount         EQU $C3C0
DEF wSndV2EnvRate          EQU $C3C1
DEF wSndV2EnvTimer         EQU $C3C2
DEF wSndV2FreqLo           EQU $C3C3
DEF wSndV2FreqHi           EQU $C3C4
DEF wSndV2Dur              EQU $C3C5
DEF wSndV3State            EQU $C3C6	; voice 3 (ch3); its Dur counts envelope steps, not frames
DEF wSndV3EnvPtr           EQU $C3C7
DEF wSndV3EnvDelta         EQU $C3C9
DEF wSndV3EnvCount         EQU $C3CA
DEF wSndV3EnvRate          EQU $C3CB
DEF wSndV3EnvTimer         EQU $C3CC
DEF wSndV3FreqLo           EQU $C3CD
DEF wSndV3FreqHi           EQU $C3CE
DEF wSndV3Dur              EQU $C3CF
DEF wSndV4State            EQU $C3D0	; voice 4 (ch4): $80 sounding, $FF idle
DEF wSndV4Dur              EQU $C3D1
DEF wSndPan                EQU $C3D2	; Play: NR51 bits for the voice (c)
DEF wSndFreqLo             EQU $C3D3	; Play: frequency from the note
DEF wSndFreqHi             EQU $C3D4
DEF wSndDuration           EQU $C3D5	; Play: length in frames (game sets it before the call)
DEF wSndGate1              EQU $C3D6	; last ch1 note byte from the sequencer; 0 (rest) mutes voice 1
DEF wSndGate2              EQU $C3D7	; same for ch2 / voice 2
DEF wMusPtr1               EQU $C3D8	; sequencer pointers
DEF wMusPtr2               EQU $C3DA
DEF wMusInst1              EQU $C3DC	; instrument for each sequencer channel (0 and 3)
DEF wMusInst2              EQU $C3DD
DEF wMusSong               EQU $C3DE	; $FF = none
DEF wMusPlaying            EQU $C3DF	; game calls WbSnd_Sequencer while nonzero

SECTION "Workboy sound envelopes A", ROM0[$0B76]

; Pitch envelopes: env_step delta, steps, frames_per_step. Every frames_per_step
; frames the voice frequency moves by delta; after `steps` steps the next entry
; loads. env_end ($63) switches the voice off.
WbEnv_Vibrato:
	env_step 4, 2, 1
	env_step -4, 2, 1
	env_step 4, 2, 1
	env_step -4, 2, 1
	env_step 4, 2, 1
	env_step -4, 2, 1
	env_step 4, 2, 1
	env_step -4, 2, 1
	env_step 4, 2, 1
	env_step -4, 2, 1
	env_end
WbEnv_Short:
	env_step 0, 1, 10
	env_end

SECTION "Workboy sound driver", ROM0[$33B1]

WbEnv_Hold:
	env_step 0, 1, 255
	env_end
WbEnv_Blip:
	env_step 0, 3, 1
	env_end

WbWave_33B9:	; ch3 wave (instruments 2 and 4)
	db $88, $88, $FF, $FF, $00, $00, $44, $44, $88, $88, $FF, $FF, $00, $00, $44, $44

WbInstTable:
	dw WbInst0, WbInst1, WbInst2, WbInst3, WbInst4, WbInst5, WbInst6
WbInst0:	inst_pulse1 $40, $F0, WbEnv_Hold
WbInst1:	inst_pulse1 $40, $F0, WbEnv_Vibrato
WbInst2:	inst_wave $20, WbEnv_Blip, WbWave_33B9
WbInst3:	inst_pulse2 $80, $F0, WbEnv_Hold
WbInst4:	inst_wave $20, WbEnv_Vibrato, WbWave_33B9
WbInst5:	inst_pulse1 $40, $F0, WbEnv_Short
WbInst6:	inst_pulse2 $80, $F0, WbEnv_Short

WbSnd_Play:
	push af	; a = note index (byte - $30), b = instrument, c = NR51 bits
	ld a,c
	ld [wSndPan],a
	pop af
	cp $D0	; note byte 0 (rest) arrives here as $D0
	jr nz, .lookup
	ld a,$FF
	ld de,$0000
.lookup:
	cp $FF
	jr z, .setFreq
	add a,a
	ld h,$00
	ld l,a
	ld de,WbFreqTable
	add hl,de
	ld e,[hl]
	inc hl
	ld d,[hl]
.setFreq:
	ld a,e
	ld [wSndFreqLo],a
	ld a,d
	and $07
	ld [wSndFreqHi],a	; (NR51 is read-modify-written below)
	ld a,$FF
	ldh [rNR50],a
	ld h,$00
	ld l,b
	add hl,hl
	ld de,WbInstTable
	add hl,de
	ld a,[hli]
	ld h,[hl]
	ld l,a
	ld a,[hli]
	cp $02
	jp z, .ch2
	jr c, .ch1
	cp $04
	jp z, .ch4
	jp .ch3
.ch1:
	ld a,[wSndDuration]
	ld [wSndV1Dur],a
	xor a
	ld [wSndV1State],a
	ld a,[wSndGate1]
	or a
	ret z	; gate: ch1 rest
	ld a,[hli]
	ldh [rNR11],a
	ld a,[hli]
	ldh [rNR12],a
	ld c,[hl]
	inc hl
	ld b,[hl]
	ld a,[bc]
	inc bc
	ld [wSndV1EnvDelta],a
	ld a,[bc]
	inc bc
	ld [wSndV1EnvCount],a
	ld a,[bc]
	inc bc
	ld [wSndV1EnvRate],a
	ld [wSndV1EnvTimer],a
	ld a,c
	ld [wSndV1EnvPtr],a
	ld a,b
	ld [wSndV1EnvPtr+1],a
	xor a
	ldh [rNR10],a
	ld a,[wSndFreqLo]
	ldh [rNR13],a
	ld [wSndV1FreqLo],a
	ld a,[wSndPan]
	ld c,a
	ldh a,[rNR51]
	and $EE
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $81
	ldh [rNR52],a
	ld a,[wSndFreqHi]
	ld [wSndV1FreqHi],a
	or $80
	ldh [rNR14],a
	ret
.ch2:
	ld a,[wSndDuration]
	ld [wSndV2Dur],a
	xor a
	ld [wSndV2State],a
	ld a,[wSndGate2]
	or a
	ret z	; gate: ch2 rest
	ld a,[hli]
	ldh [rNR21],a
	ld a,[hli]
	ldh [rNR22],a
	ld c,[hl]
	inc hl
	ld b,[hl]
	ld a,[bc]
	inc bc
	ld [wSndV2EnvDelta],a
	ld a,[bc]
	inc bc
	ld [wSndV2EnvCount],a
	ld a,[bc]
	inc bc
	ld [wSndV2EnvRate],a
	ld [wSndV2EnvTimer],a
	ld a,c
	ld [wSndV2EnvPtr],a
	ld a,b
	ld [wSndV2EnvPtr+1],a
	ld a,[wSndFreqLo]
	ldh [rNR23],a
	ld [wSndV2FreqLo],a
	ld a,[wSndPan]
	add a,a
	ld c,a
	ldh a,[rNR51]
	and $DD
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $82
	ldh [rNR52],a
	ld a,[wSndFreqHi]
	ld [wSndV2FreqHi],a
	or $80
	ldh [rNR24],a
	ret
.ch3:
	ld a,[wSndDuration]
	ld [wSndV3Dur],a
	ld a,[hli]
	ldh [rNR32],a
	ld c,[hl]
	inc hl
	ld b,[hl]
	inc hl
	ld a,[hli]
	ld h,[hl]
	ld l,a
	push bc
	ld bc,$1030	; b = 16 bytes, c = $30 (wave RAM)
.waveLoop:
	ld a,[hli]
	ldh [c],a
	inc c
	dec b
	jr nz, .waveLoop
	pop bc
	xor a
	ld [wSndV3State],a
	ld a,[bc]
	inc bc
	ld [wSndV3EnvDelta],a
	ld a,[bc]
	inc bc
	ld [wSndV3EnvCount],a
	ld a,[bc]
	inc bc
	ld [wSndV3EnvRate],a
	ld [wSndV3EnvTimer],a
	ld a,c
	ld [wSndV3EnvPtr],a
	ld a,b
	ld [wSndV3EnvPtr+1],a
	ld a,$80
	ldh [rNR30],a
	ld a,[wSndFreqLo]
	ld [wSndV3FreqLo],a
	ldh [rNR33],a
	ld a,[wSndPan]
	add a,a
	add a,a
	ld c,a
	ldh a,[rNR51]
	and $BB
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $84
	ldh [rNR52],a
	ld a,[wSndFreqHi]
	ld [wSndV3FreqHi],a
	or $80
	ldh [rNR34],a
	ret
.ch4:
	ld a,[wSndDuration]
	ld [wSndV4Dur],a
	ld a,[hli]
	ldh [rNR42],a
	ld a,[hli]
	ldh [rNR43],a
	ld a,[wSndPan]
	add a,a
	add a,a
	add a,a
	ld c,a
	ldh a,[rNR51]
	and $77
	or c
	ldh [rNR51],a
	ldh a,[rNR52]
	or $88
	ldh [rNR52],a
	ld a,$80
	ldh [rNR44],a
	ld [wSndV4State],a
	ret
WbSnd_Voices:
	ld a,[wSndV1State]
	inc a
	jp z, .ch2
	ld a,[wSndV1Dur]
	dec a
	ld [wSndV1Dur],a
	jp z, .ch1Off
	ld a,[wSndGate1]	; gate closed: mute ch1
	or a
	jr nz, .ch1Env
	ldh a,[rNR51]
	and $EE
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FE
	ldh [rNR52],a
	jp .ch2
.ch1Env:
	ld a,[wSndV1EnvTimer]
	dec a
	jr z, .ch1Step
	ld [wSndV1EnvTimer],a
	jr .ch2
.ch1Step:
	ld a,[wSndV1EnvRate]
	ld [wSndV1EnvTimer],a
	ld a,[wSndV1EnvDelta]
	ld c,a
	bit 7,a
	jr z, .ch1Pos
	ld a,[wSndV1FreqLo]
	add a,c
	ld [wSndV1FreqLo],a
	ldh [rNR13],a
	ld a,[wSndV1FreqHi]
	sbc a,$FF
	ld [wSndV1FreqHi],a
	ldh [rNR14],a
	jr .ch1Count
.ch1Pos:
	ld a,[wSndV1FreqLo]
	add a,c
	ld [wSndV1FreqLo],a
	ldh [rNR13],a
	ld a,[wSndV1FreqHi]
	adc a,$00
	ld [wSndV1FreqHi],a
	ldh [rNR14],a
.ch1Count:
	ld a,[wSndV1EnvCount]
	dec a
	jr z, .ch1Next
	ld [wSndV1EnvCount],a
	jr .ch2
.ch1Next:
	ld a,[wSndV1EnvPtr]
	ld l,a
	ld a,[wSndV1EnvPtr+1]
	ld h,a
	ld a,[hli]
	cp $63	; $63 = envelope end, voice off
	jr z, .ch1Off
	ld [wSndV1EnvDelta],a
	ld a,[hli]
	ld [wSndV1EnvCount],a
	ld a,[hli]
	ld [wSndV1EnvRate],a
	ld [wSndV1EnvTimer],a
	ld a,l
	ld [wSndV1EnvPtr],a
	ld a,h
	ld [wSndV1EnvPtr+1],a
	jr .ch2
.ch1Off:
	ldh a,[rNR51]
	and $EE
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FE
	ldh [rNR52],a
	ld a,$FF
	ld [wSndV1State],a
.ch2:
	ld a,[wSndV2State]
	inc a
	jp z, .ch3
	ld a,[wSndV2Dur]
	dec a
	ld [wSndV2Dur],a
	jp z, .ch2Off
	ld a,[wSndGate2]
	or a
	jr nz, .ch2Env
	jp .ch3
.ch2Env:
	ld a,[wSndV2EnvTimer]
	dec a
	jr z, .ch2Step
	ld [wSndV2EnvTimer],a
	jr .ch3
.ch2Step:
	ld a,[wSndV2EnvRate]
	ld [wSndV2EnvTimer],a
	ld a,[wSndV2EnvDelta]
	ld c,a
	bit 7,a
	jr z, .ch2Pos
	ld a,[wSndV2FreqLo]
	add a,c
	ld [wSndV2FreqLo],a
	ldh [rNR23],a
	ld a,[wSndV2FreqHi]
	sbc a,$FF
	ld [wSndV2FreqHi],a
	ldh [rNR24],a
	jr .ch2Count
.ch2Pos:
	ld a,[wSndV2FreqLo]
	add a,c
	ld [wSndV2FreqLo],a
	ldh [rNR23],a
	ld a,[wSndV2FreqHi]
	adc a,$00
	ld [wSndV2FreqHi],a
	ldh [rNR24],a
.ch2Count:
	ld a,[wSndV2EnvCount]
	dec a
	jr z, .ch2Next
	ld [wSndV2EnvCount],a
	jr .ch3
.ch2Next:
	ld a,[wSndV2EnvPtr]
	ld l,a
	ld a,[wSndV2EnvPtr+1]
	ld h,a
	ld a,[hli]
	cp $63	; $63 = envelope end
	jr z, .ch2Off
	ld [wSndV2EnvDelta],a
	ld a,[hli]
	ld [wSndV2EnvCount],a
	ld a,[hli]
	ld [wSndV2EnvRate],a
	ld [wSndV2EnvTimer],a
	ld a,l
	ld [wSndV2EnvPtr],a
	ld a,h
	ld [wSndV2EnvPtr+1],a
	jr .ch3
.ch2Off:
	ldh a,[rNR51]
	and $DD
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FD
	ldh [rNR52],a
	ld a,$FF
	ld [wSndV2State],a
.ch3:
	ld a,[wSndV3EnvTimer]
	dec a
	jr z, .ch3Step
	ld [wSndV3EnvTimer],a
	jp .ch4
.ch3Step:
	ld a,[wSndV3Dur]
	dec a
	ld [wSndV3Dur],a
	jr z, .ch3Off
	ld a,[wSndV3EnvRate]
	ld [wSndV3EnvTimer],a
	ld a,[wSndV3EnvDelta]
	ld c,a
	bit 7,a
	jr z, .ch3Pos
	ld a,[wSndV3FreqLo]
	add a,c
	ld [wSndV3FreqLo],a
	ldh [rNR33],a
	ld a,[wSndV3FreqHi]
	sbc a,$FF
	ld [wSndV3FreqHi],a
	ldh [rNR34],a
	jr .ch3Count
.ch3Pos:
	ld a,[wSndV3FreqLo]
	add a,c
	ld [wSndV3FreqLo],a
	ldh [rNR33],a
	ld a,[wSndV3FreqHi]
	adc a,$00
	ld [wSndV3FreqHi],a
	ldh [rNR34],a
.ch3Count:
	ld a,[wSndV3EnvCount]
	dec a
	jr z, .ch3Next
	ld [wSndV3EnvCount],a
	jr .ch4
.ch3Next:
	ld a,[wSndV3EnvPtr]
	ld l,a
	ld a,[wSndV3EnvPtr+1]
	ld h,a
	ld a,[hli]
	cp $63	; $63 = envelope end
	jr z, .ch3Off
	ld [wSndV3EnvDelta],a
	ld a,[hli]
	ld [wSndV3EnvCount],a
	ld a,[hli]
	ld [wSndV3EnvRate],a
	ld [wSndV3EnvTimer],a
	ld a,l
	ld [wSndV3EnvPtr],a
	ld a,h
	ld [wSndV3EnvPtr+1],a
	jr .ch4
.ch3Off:
	ldh a,[rNR51]
	and $BB
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FB
	ldh [rNR52],a
	ld a,$FF
	ld [wSndV3State],a
.ch4:
	ld a,[wSndV4State]
	inc a
	ret z
	ld a,[wSndV4Dur]
	dec a
	ld [wSndV4Dur],a
	ret nz
	dec a
	ld [wSndV4State],a
	ldh a,[rNR51]
	and $77
	ldh [rNR51],a
	ldh a,[rNR52]
	and $F7
	ldh [rNR52],a
	ret
WbSnd_PlaySong:
	ld [wMusSong],a
	push af
	call WbSnd_StopMusic
	xor a
	ld [wMusInst1],a
	ld a,$03
	ld [wMusInst2],a
	pop af
	add a,a
	add a,a
	ld e,a
	ld d,$00
	ld hl,WbSongTable
	add hl,de
	ld a,[hli]
	ld [wMusPtr2],a
	ld a,[hli]
	ld [wMusPtr2+1],a
	ld a,[hli]
	ld [wMusPtr1],a
	ld a,[hli]
	ld [wMusPtr1+1],a
	ld a,$01
	ld [wMusPlaying],a
	ret
WbSnd_Sequencer:
	ld a,[wSndV1State]
	inc a
	jr nz, .ch2
	ld a,[wMusPtr1]
	ld l,a
	ld a,[wMusPtr1+1]
	ld h,a
.ch1Read:
	ld a,[hli]
	cp $FF
	jp z, WbSnd_StopMusic
	cp $F0
	jr c, .ch1Note
	and $0F	; $F0-$FE: low nibble discarded, byte skipped
	jr .ch1Read
.ch1Note:
	ld [wSndGate1],a
	sub $30	; note byte -> index
	ld c,a
	ld a,[hli]
	ld [wSndDuration],a
	ld a,l
	ld [wMusPtr1],a
	ld a,h
	ld [wMusPtr1+1],a
	ld a,[wMusInst1]
	ld b,a
	ld a,c
	ld c,$11	; NR51 bits $11
	call WbSnd_Play
.ch2:
	ld a,[wSndV2State]
	inc a
	jr nz, .done
	ld a,[wMusPtr2]
	ld l,a
	ld a,[wMusPtr2+1]
	ld h,a
.ch2Read:
	ld a,[hli]
	cp $FF
	jp z, WbSnd_StopMusic
	cp $F0
	jr c, .ch2Note
	and $0F
	jr .ch2Read
.ch2Note:
	ld [wSndGate2],a
	sub $30
	ld c,a
	ld a,[hli]
	ld [wSndDuration],a
	ld a,l
	ld [wMusPtr2],a
	ld a,h
	ld [wMusPtr2+1],a
	ld a,[wMusInst2]
	ld b,a
	ld a,c
	ld c,$11	; NR51 bits $11
	call WbSnd_Play
.done:
	ret
WbSnd_StopMusic:
	ld a,$FF
	ld [wMusSong],a
	ldh a,[rNR51]
	xor a
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FE
	ldh [rNR52],a
	ldh a,[rNR51]
	xor a
	ldh [rNR51],a
	ldh a,[rNR52]
	and $FD
	ldh [rNR52],a
	xor a
	ld [wMusPlaying],a
	ret

; 48 notes, C2-B5
WbFreqTable:
	dw $002C, $009D, $0107, $016B, $01CA, $0223, $0277, $02C7, $0312, $0359, $039B, $03DA
	dw $0416, $044E, $0483, $04B6, $04E5, $0511, $053C, $0563, $0589, $05AC, $05CF, $05ED
	dw $060B, $0627, $0642, $065B, $0672, $0689, $069E, $06B1, $06C4, $06D6, $06E7, $06F6
	dw $0705, $0714, $0721, $072D, $0739, $0744, $074F, $0759, $0762, $076B, $0773, $077B

; Song = (ch2 sequence, ch1 sequence). Song 15 lives in bank 3 and only plays
; correctly while bank 3 is mapped.
WbSongTable:
	dw WbSong00_Ch2, WbSong00_Ch1	; 0
	dw WbSong01_Ch2, WbSong01_Ch1	; 1
	dw WbSong02_Ch2, WbSong02_Ch1	; 2
	dw WbSong03_Ch2, WbSong03_Ch1	; 3
	dw WbSong04_Ch2, WbSong04_Ch1	; 4
	dw WbSong05_Ch2, WbSong05_Ch1	; 5
	dw WbSong06_Ch2, WbSong06_Ch1	; 6
	dw WbSong07_Ch2, WbSong07_Ch1	; 7
	dw WbSong08_Ch2, WbSong08_Ch1	; 8
	dw WbSong09_Ch2, WbSong09_Ch1	; 9
	dw WbSong10_Ch2, WbSong10_Ch1	; 10
	dw WbSong11_Ch2, WbSong11_Ch1	; 11
	dw WbSong12_Ch2, WbSong12_Ch1	; 12
	dw WbSong13_Ch2, WbSong13_Ch1	; 13
	dw WbSong14_Ch2, WbSong14_Ch1	; 14
	dw WbSong15_Ch2, WbSong15_Ch1	; 15

; $38CD-$398D is game code and data (a graphics loader and its table), not sound.

SECTION "Workboy music", ROM0[$398E]

; Sequences: note NOTE, frames / rest frames / snd_inst n (ignored by the driver)
; / snd_end (stops all music; the $01 after each $FF is never read).
WbSong00_Ch2:
	rest 24
	snd_inst 0
	note Cs3, 24
	note Cs4, 24
	note Gs3, 24
	note C_4, 24
	note As3, 24
	note Cs4, 24
	note Fs3, 24
	note As3, 24
	note Cs3, 24
	note Gs3, 24
	note Cs3, 24
	note Ds4, 12
	note Cs4, 12
	note C_4, 24
	note C_4, 12
	note C_4, 12
	note Cs3, 24
	snd_end

WbSong00_Ch1:
	snd_inst 0
	note Cs4, 12
	note Ds4, 12
	note F_4, 24
	note F_4, 12
	note F_4, 12
	note Ds4, 24
	note Ds4, 24
	note Cs4, 12
	note Ds4, 12
	note F_4, 12
	note Cs4, 12
	note As3, 12
	note C_4, 12
	note Cs4, 24
	note Gs3, 24
	note Cs4, 12
	note F_4, 12
	note Gs4, 24
